def _read_video_frames_uint8(video_path):
    """v1 read_video_frames_torch's frames as uint8 [T, C, H, W] -- what
    _prepare_video_inputs turned them into at once (bug sweep 2026-10-09,
    A11: two float32 copies of the whole clip and a third at the * 255 for a
    lossless round trip)."""
    frames_numpy, fps, _, _, _, _, video_stream_info = read_video_frames_decord(video_path=video_path,
                                                                                as_uint8=True)
    return torch.from_numpy(frames_numpy).permute(0, 3, 1, 2), fps, video_stream_info


class _MessageBoxShim:
    """v1 calls tkinter.messagebox from the engine; here each becomes a toast."""

    def __init__(self):
        self.hooks = None  # set by InpaintingEngine.__init__

    def _send(self, kind, title, message):
        hooks = self.hooks
        if hooks is not None:
            hooks.message(kind, str(title), str(message))
        else:
            logger.warning("%s: %s", title, message)

    def showerror(self, title="", message="", **_kw):
        self._send("error", title, message)

    def showwarning(self, title="", message="", **_kw):
        self._send("warning", title, message)

    def showinfo(self, title="", message="", **_kw):
        self._send("info", title, message)


