        frames, fps, video_stream_info = _read_video_frames_uint8(input_video_path)  # v2: bug sweep A11

        # --- Process Length Logic ---
        # --- FIX: Ensure frames are integers (0-255) before splitting. ---
        # The read_video_frames function now returns floats (0-1), but the
        # splitting logic expects integers. We convert back to uint8 here.
        # v2: already uint8 (read so, bug sweep A11)
        total_frames_in_video = frames.shape[0]
        actual_frames_to_process_count = total_frames_in_video

        if process_length != -1 and process_length > 0:
            actual_frames_to_process_count = min(total_frames_in_video, process_length)
            logger.info(
                f"Limiting processing to first {actual_frames_to_process_count} frames (out of {total_frames_in_video})."
            )

        if actual_frames_to_process_count == 0:
            logger.warning(f"No frames to process in {input_video_path} (after applying process_length), skipping.")
            if update_info_callback:
                self.after(
                    0,
                    lambda: update_info_callback(
                        base_video_name,
                        "N/A",
                        f"0 (out of {total_frames_in_video})",
                        overlap,
                        original_input_blend_strength,
                    ),
                )
            return None

        frames = frames[:actual_frames_to_process_count]
        num_frames_original = frames.shape[0]

        if num_frames_original == 0:
            logger.warning(f"No frames found in {input_video_path}, skipping.")
            if update_info_callback:
                self.after(
                    0,
                    lambda: update_info_callback(
                        base_video_name, "N/A", "0 (skipped)", overlap, original_input_blend_strength
                    ),
                )
            return None

        # --- Dimension Divisibility Check and Resizing (if needed) ---
        _, _, total_h_raw_input_before_resize, total_w_raw_input_before_resize = frames.shape
        required_divisor = 8

        new_h = total_h_raw_input_before_resize
        new_w = total_w_raw_input_before_resize

        if new_h % required_divisor != 0:
            new_h = (new_h // required_divisor + 1) * required_divisor
            logger.warning(
                f"Video height {total_h_raw_input_before_resize} is not divisible by {required_divisor}. Resizing to {new_h}."
            )

        if new_w % required_divisor != 0:
            new_w = (new_w // required_divisor + 1) * required_divisor
            logger.warning(
                f"Video width {total_w_raw_input_before_resize} is not divisible by {required_divisor}. Resizing to {new_w}."
            )

        if new_h != total_h_raw_input_before_resize or new_w != total_w_raw_input_before_resize:
            if frames.shape[0] > 0:
                frames = F.interpolate(frames, size=(new_h, new_w), mode="bicubic", align_corners=False)
                logger.info(
                    f"Frames resized from {total_h_raw_input_before_resize}x{total_w_raw_input_before_resize} to {new_h}x{new_w}."
                )
            else:
                logger.warning("Attempted to resize empty frames tensor. Skipping resize.")

        # --- Update current dimensions after potential resize ---
        total_h_current, total_w_current = frames.shape[2], frames.shape[3]

        if total_h_current < required_divisor or total_w_current < required_divisor:
            error_msg = (
                f"Video {base_video_name} is too small after resize ({total_w_current}x{total_h_current}), skipping."
            )
            logger.error(error_msg)
            if update_info_callback:
                self.after(
                    0,
                    lambda: update_info_callback(
                        base_video_name,
                        f"{total_w_current}x{total_h_current} (INVALID)",
                        num_frames_original,
                        overlap,
                        original_input_blend_strength,
                    ),
                )
            self.after(0, lambda: messagebox.showerror("Input Error", error_msg))
            return None

        # --- Input Splitting based on Dual/Quad ---
        frames_left_original_cropped: Optional[torch.Tensor] = None  # For SBS output, cropped to original length

        if is_dual_eye_input:
            # 4-panel: [Lmask | Lwarp] over [Rmask | Rwarp].
            # Stack the two eyes along the temporal axis -> a 2N-length batch so the
            # existing mask/tiling/UNet path inpaints both eyes in one pass.
            # Left-eye frames come first, right-eye frames second.
            half_h = total_h_current // 2
            half_w = total_w_current // 2

            left_mask_q = frames[:, :, :half_h, :half_w]   # top-left
            left_warp_q = frames[:, :, :half_h, half_w:]   # top-right
            right_mask_q = frames[:, :, half_h:, :half_w]  # bottom-left
            right_warp_q = frames[:, :, half_h:, half_w:]  # bottom-right

            # Temporal stack: [L0..Ln, R0..Rn]
            # v2 (bug sweep A7): the right eye reversed, so the seam joins Ln and Rn
            frames_warpped_raw = torch.cat([left_warp_q, torch.flip(right_warp_q, dims=[0])], dim=0)
            frames_mask_raw = torch.cat([left_mask_q, torch.flip(right_mask_q, dims=[0])], dim=0)

            output_display_h = half_h
            output_display_w = half_w

            # --- Auto-pad to a multiple of 8 (UNet latent requirement) ---
            # Rather than reject odd sizes (e.g. 1600x900), pad the bottom/right edge
            # up to the next multiple of 8. The finalize stage crops back to the
            # original per-eye dimensions, so output size is unchanged.
            required_divisor = 8
            pad_h = (required_divisor - (half_h % required_divisor)) % required_divisor
            pad_w = (required_divisor - (half_w % required_divisor)) % required_divisor
            if pad_h or pad_w:
                logger.info(
                    f"Dual-eye '{base_video_name}': per-eye {half_w}x{half_h} not divisible by "
                    f"{required_divisor}; padding to {half_w + pad_w}x{half_h + pad_h} for inpainting "
                    f"(cropped back afterward)."
                )
                # F.pad pads last dim first: (W_left, W_right, H_top, H_bottom)
                frames_warpped_raw = F.pad(
                    frames_warpped_raw.float(), (0, pad_w, 0, pad_h), mode="replicate"
                )
                frames_mask_raw = F.pad(
                    frames_mask_raw.float(), (0, pad_w, 0, pad_h), mode="constant", value=0.0
                )
                # Track the padding so finalize can crop back to (half_h, half_w).
                self._dual_eye_pad = (pad_h, pad_w, half_h, half_w)
            else:
                self._dual_eye_pad = (0, 0, half_h, half_w)

        elif is_dual_input:
            half_w = total_w_current // 2
            frames_mask_raw = frames[:, :, :, :half_w]  # Left half is mask
            frames_warpped_raw = frames[:, :, :, half_w:]  # Right half is warped

            # The target_output_h/w for GUI info will be the dimensions of the inpainted part
            output_display_h = total_h_current
            output_display_w = half_w

            # --- NEW: Divisibility Check ---
            required_divisor = 8
            if output_display_h % required_divisor != 0 or output_display_w % required_divisor != 0:
                error_msg = (
                    f"Video '{base_video_name}' has an invalid resolution for inpainting.\n\n"
                    f"The target inpainting area has dimensions {output_display_w}x{output_display_h}, "
                    f"but both width and height must be divisible by {required_divisor}.\n\n"
                    "Please crop or resize the source video. Skipping this file."
                )
                logger.error(error_msg)
                if update_info_callback:
                    self.after(
                        0,
                        lambda: update_info_callback(
                            base_video_name, f"{output_display_w}x{output_display_h} (INVALID)", "Skipped", "N/A", "N/A"
                        ),
                    )
                self.after(0, lambda: messagebox.showerror("Resolution Error", error_msg))
                return None
            # --- END NEW ---

        else:  # Quad input
            half_h = total_h_current // 2
            half_w = total_w_current // 2

            # frames_left_original_full_padded is the top-left quadrant, padded temporally
            frames_left_original_full_padded = frames[:, :, :half_h, :half_w]
            # Now, crop it to the original video length for eventual SBS concatenation
            frames_left_original_cropped = (
                frames_left_original_full_padded[:num_frames_original].float() / 255.0
            )  # Normalize for concat

            frames_mask_raw = frames[:, :, half_h:, :half_w]  # Bottom-Left is mask
            frames_warpped_raw = frames[:, :, half_h:, half_w:]  # Bottom-Right is warped

            output_display_h = half_h
            output_display_w = half_w

            # --- NEW: Divisibility Check ---
            required_divisor = 8
            if output_display_h % required_divisor != 0 or output_display_w % required_divisor != 0:
                error_msg = (
                    f"Video '{base_video_name}' has an invalid resolution for inpainting.\n\n"
                    f"The target inpainting area has dimensions {output_display_w}x{output_display_h}, "
                    f"but both width and height must be divisible by {required_divisor}.\n\n"
                    "Please crop or resize the source video. Skipping this file."
                )
                logger.error(error_msg)
                if update_info_callback:
                    self.after(
                        0,
                        lambda: update_info_callback(
                            base_video_name, f"{output_display_w}x{output_display_h} (INVALID)", "Skipped", "N/A", "N/A"
                        ),
                    )
                self.after(0, lambda: messagebox.showerror("Resolution Error", error_msg))
                return None
            # --- END NEW ---

        # --- Normalization and Grayscale Conversion (Using OpenCV) ---
        # For dual-eye, the warped/mask batches are now 2N (left eye stacked over right).
        # Bump num_frames_original to the stacked length so downstream [:num_frames_original]
        # crops retain BOTH eyes. The per-eye count is recovered at SBS assembly.
        if is_dual_eye_input:
            num_frames_original = frames_warpped_raw.shape[0]

        # --- FIX: Normalize the warped frames here ---
        frames_warpped_normalized = frames_warpped_raw.float() / 255.0
