# -- v1 read_video_frames_torch (inpainting_gui.py:5396)
def read_video_frames_torch(video_path: str, decord_ctx=cpu(0)) -> Tuple[torch.Tensor, float, Optional[dict]]:
    """
    Reads a video using decord and returns frames as a 4D float tensor [T, C, H, W], the FPS,
    and video stream metadata.
    """
    frames_numpy, fps, _, _, _, _, video_stream_info = read_video_frames_decord(
        video_path=video_path, decord_ctx=decord_ctx
    )
    return torch.from_numpy(frames_numpy).permute(0, 3, 1, 2).float(), fps, video_stream_info


# -- v1 blend_h (inpainting_gui.py:5407)
def blend_h(a: torch.Tensor, b: torch.Tensor, overlap_size: int) -> torch.Tensor:
    """
    Blend two tensors horizontally along the right edge of `a` and left edge of `b`.
    """
    weight_b = (torch.arange(overlap_size).view(1, 1, 1, -1) / overlap_size).to(b.device)
    b[:, :, :, :overlap_size] = (1 - weight_b) * a[:, :, :, -overlap_size:] + weight_b * b[:, :, :, :overlap_size]
    return b


# -- v1 blend_v (inpainting_gui.py:5416)
def blend_v(a: torch.Tensor, b: torch.Tensor, overlap_size: int) -> torch.Tensor:
    """
    Blend two tensors vertically along the bottom edge of `a` and top edge of `b`.
    """
    weight_b = (torch.arange(overlap_size).view(1, 1, -1, 1) / overlap_size).to(b.device)
    b[:, :, :overlap_size, :] = (1 - weight_b) * a[:, :, -overlap_size:, :] + weight_b * b[:, :, :overlap_size, :]
    return b


# -- v1 spatial_tiled_process (inpainting_gui.py:5428)
def spatial_tiled_process(
    cond_frames: torch.Tensor,
    mask_frames: torch.Tensor,
    process_func,
    tile_num: int,
    spatial_n_compress: int = 8,
    num_inference_steps: int = 5,
    **kwargs,
) -> torch.Tensor:
    """
    Splits frames into tiles, processes them with `process_func`, then blends the results back together.
    Ensures that tile dimensions are divisible by `spatial_n_compress` to avoid pipeline errors.
    """
    height = cond_frames.shape[2]
    width = cond_frames.shape[3]

    tile_overlap = (128, 128)
    # Ensure overlap is divisible by compress factor (8)
    overlap_y = (tile_overlap[0] // spatial_n_compress) * spatial_n_compress
    overlap_x = (tile_overlap[1] // spatial_n_compress) * spatial_n_compress

    # Calculate stride such that (stride + overlap) is divisible by 8 and covers the entire dimension.
    # stride * (tile_num - 1) + (stride + overlap) >= dimension  => stride * tile_num + overlap >= dimension.
    stride_y = (height - overlap_y + tile_num - 1) // tile_num
    stride_y = ((stride_y + spatial_n_compress - 1) // spatial_n_compress) * spatial_n_compress
    stride_y = max(stride_y, spatial_n_compress)

    stride_x = (width - overlap_x + tile_num - 1) // tile_num
    stride_x = ((stride_x + spatial_n_compress - 1) // spatial_n_compress) * spatial_n_compress
    stride_x = max(stride_x, spatial_n_compress)

    tile_size_y = stride_y + overlap_y
    tile_size_x = stride_x + overlap_x

    # Pad input frames if necessary to perfectly fit the calculated tiles
    padded_height = stride_y * (tile_num - 1) + tile_size_y
    padded_width = stride_x * (tile_num - 1) + tile_size_x

    pad_bottom = padded_height - height
    pad_right = padded_width - width

    if pad_bottom > 0 or pad_right > 0:
        logger.debug(f"Padding frames from ({height}x{width}) to ({padded_height}x{padded_width}) for tiling.")
        cond_frames = F.pad(cond_frames, (0, pad_right, 0, pad_bottom), mode="reflect")
        mask_frames = F.pad(mask_frames, (0, pad_right, 0, pad_bottom), mode="constant", value=0.0)

    cols = []
    for i in range(tile_num):
        row_tiles = []
        for j in range(tile_num):
            y_start = i * stride_y
            x_start = j * stride_x
            y_end = y_start + tile_size_y
            x_end = x_start + tile_size_x

            cond_tile = cond_frames[:, :, y_start:y_end, x_start:x_end]
            mask_tile = mask_frames[:, :, y_start:y_end, x_start:x_end]

            if cond_tile.numel() == 0 or mask_tile.numel() == 0:
                logger.warning(
                    f"Skipping empty tile: y_start={y_start}, y_end={y_end}, x_start={x_start}, x_end={x_end}"
                )
                continue

            with torch.no_grad():
                tile_output = process_func(
                    frames=cond_tile,
                    frames_mask=mask_tile,
                    height=cond_tile.shape[2],
                    width=cond_tile.shape[3],
                    num_frames=len(cond_tile),
                    output_type="latent",
                    num_inference_steps=num_inference_steps,
                    **kwargs,
                ).frames[0]

            row_tiles.append(tile_output)
        cols.append(row_tiles)

    latent_stride = (stride_y // spatial_n_compress, stride_x // spatial_n_compress)
    latent_overlap = (overlap_y // spatial_n_compress, overlap_x // spatial_n_compress)

    blended_rows = []
    for i, row_tiles in enumerate(cols):
        row_result = []
        for j, tile in enumerate(row_tiles):
            if i > 0:
                if len(cols[i - 1]) > j and cols[i - 1][j] is not None:
                    tile = blend_v(cols[i - 1][j], tile, latent_overlap[0])
            if j > 0:
                if len(row_result) > j - 1 and row_result[j - 1] is not None:
                    tile = blend_h(row_result[j - 1], tile, latent_overlap[1])
            row_result.append(tile)
        blended_rows.append(row_result)

    final_rows = []
    for i, row_tiles in enumerate(blended_rows):
        for j, tile in enumerate(row_tiles):
            if tile is None:
                logger.warning(f"Skipping None tile during final row concatenation at ({i}, {j})")
                continue  # Skip None tiles, this might cause dimension mismatch later if not handled

            # Ensure the slice is valid and does not result in empty tensor
            if i < len(blended_rows) - 1:
                if latent_stride[0] > 0:
                    tile = tile[:, :, : latent_stride[0], :]
                else:
                    logger.warning(f"latent_stride[0] is zero, skipping vertical crop for tile ({i}, {j}).")
            if j < len(row_tiles) - 1:
                if latent_stride[1] > 0:
                    tile = tile[:, :, :, : latent_stride[1]]
                else:
                    logger.warning(f"latent_stride[1] is zero, skipping horizontal crop for tile ({i}, {j}).")
            row_tiles[j] = tile

        # Filter out None tiles before concatenation
        valid_row_tiles = [t for t in row_tiles if t is not None]
        if valid_row_tiles:
            final_rows.append(torch.cat(valid_row_tiles, dim=3))
        else:
            logger.warning(f"Row {i} ended up empty after filtering None tiles.")

    if not final_rows:
        logger.error(
            "No final rows to concatenate after spatial tiling. This indicates a major issue with tile processing or blending."
        )
        raise ValueError("Spatial tiling failed to produce any valid output rows.")

    x = torch.cat(final_rows, dim=2)

    # Crop the latents back to the original (relative) dimensions.
    # Since the pipeline requires 8-divisible input, and we assuming the input was already such,
    # cropping to height//8 and width//8 is exact.
    latent_h = height // spatial_n_compress
    latent_w = width // spatial_n_compress
    x = x[:, :, :latent_h, :latent_w]

    return x
